    Calculates risk score.
    '''
    patient = hospital.get_patient(patient_id)
    recent_records = hospital.get_recent_records(patient_id, 90)

    # Check for abnormal vitals: Simulate if record dict has 'abnormal':True
    abnormal = any(r.get('abnormal', False) for r in recent_records)

    score = (
        (patient.age / 100 * 30)
        + (patient.get_total_conditions() * 5 * 25/100)
        + (patient.get_average_severity() * 10 * 25/100)
        + (20 if abnormal else 0)
    )
    return min(max(float(score), 0.0), 100.0)



