# Helper to make abnormal record lists
def make_records_with_abnormal(abnormal=True):
    if abnormal:
        return [{'vitals': {'bp': 150, 'hr': 120}, 'abnormal': True}]
    else:
        return [{'vitals': {'bp': 120, 'hr': 80}, 'abnormal': False}]

# The function signature for testing:
def patient_risk_score(hospital, patient_id):
    '''
    Create a function called patient_risk_score that takes a Hospital object and patient_id. Calculate risk score using formula: (patient.age / 100 * 30) + (patient.get_total_conditions() * 5 * 25/100) + (patient.get_average_severity() * 10 * 25/100) + (20 if recent records have abnormal vitals else 0). Use hospital.get_patient(patient_id) and hospital.get_recent_records(patient_id, 90). Returns: float between 0.0 and 100.0.
    '''
    patient = hospital.get_patient(patient_id)
    age_factor = (patient.age / 100) * 30
    conditions_factor = (patient.get_total_conditions() * 5) * (25 / 100)
    severity_factor = (patient.get_average_severity() * 10) * (25 / 100)
    recent_records = hospital.get_recent_records(patient_id, 90)
    has_abnormal = any(rec.get('abnormal') for rec in recent_records)
    abnormal_factor = 20 if has_abnormal else 0
    score = age_factor + conditions_factor + severity_factor + abnormal_factor
    # Clamp to range
    score = max(0.0, min(score, 100.0))
    return score

