    def convert_row(row):
        # Type conversions for detailed mode
        int_cols = {'technical_score', 'communication_score',
                    'teamwork_score', 'leadership_score'}
        float_cols = {'overall_rating'}
        new_row = {}
        for k, v in row.items():
